import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BDKIrnCI.js";const c=JSON.parse('{"title":"AppleSkinPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/apple-skin-pumpkin/README.md"},"headers":[],"relativePath":"packages/apple-skin-pumpkin/README.md","filePath":"packages/apple-skin-pumpkin/README.md"}'),o={name:"packages/apple-skin-pumpkin/README.md"};function s(p,e,r,l,h,d){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="appleskinpumpkin" tabindex="-1">AppleSkinPumpkin <a class="header-anchor" href="#appleskinpumpkin" aria-label="Permalink to &quot;AppleSkinPumpkin&quot;">​</a></h1><p>AppleSkin server-side support</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/api/plugins/apple-skin-pumpkin/" target="_blank" rel="noreferrer">AppleSkinPumpkin API reference</a> on the documentation site.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Put <code>apple-skin-pumpkin.wasm</code> from the plugin&#39;s GitHub release in your server&#39;s <code>plugins/</code> folder and restart. Hot reload cannot ask for permissions, so the first load needs a restart.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Vanilla tells a client about saturation only when it reaches zero, and never sends exhaustion at all, which leaves the food tooltips AppleSkin draws behind by a tick. So the plugin reads every online player once per tick and sends the two values, plus whether the world heals players by food. It sends only what moved since the last packet, so a still player costs nothing.</p><p>AppleSkin is a Java Edition mod, so Bedrock players are skipped.</p><h2 id="seeing-what-it-does" tabindex="-1">Seeing what it does <a class="header-anchor" href="#seeing-what-it-does" aria-label="Permalink to &quot;Seeing what it does&quot;">​</a></h2><p>Set <code>log.level</code> to <code>debug</code> in your Pumpkin config. Every packet the plugin sends is then logged with the player and the value, along with players joining, leaving and being skipped. Ticks where nothing changed are silent, which is the point of only sending on a change.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Pumpkin asks for these on the server console the first time the plugin loads.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>http.outbound</code></td><td>Check Pumpkin Market for plugin updates.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>This plugin registers no commands.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>This plugin has no configuration file.</p>',17)])])}const k=a(o,[["render",s]]);export{c as __pageData,k as default};
